import React from 'react';
import styled from '@emotion/styled';

const BoardWrapper:React.FC = ({children}) => {

    const Wrapper = styled.div`
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
    `;

    return(
        <Wrapper>
            {children}
        </Wrapper>
    );
}

export default BoardWrapper