import React from 'react';
import styled from '@emotion/styled';
import {Link} from 'react-router-dom';
import marked from 'marked';

interface itemType{
    title: string; 
    author: string;
    create_at: string;
    note: string;
    name: string;
}

const BoardItem:React.FC<itemType> = ({title, author, create_at, note, name}) => {

    const getMarkdownText = () => {
        const rawMarkup = marked(note, {sanitize: true});
        return { __html: rawMarkup}
    }

    const Item = styled.li`

        border: 1px solid black;
        border-radius: 10px;

        padding: 10px;
        margin: 10px;

        list-style: none;
    `;

    const DivInfo = styled.div`
        display: flex;
        justify-content: space-between;
    `;
    const DivTitle = styled.div`
        & > a{
            text-decoration: none;

            :active {

            }
        }
    `;

    const BoardTitle = styled.h3`
        text-align: center;
    `;
    const DivNote = styled.div`
        border: 1px solid gray;
        padding: 1%;
        margin: 0 10%;
    `;

    return(
        <Item>
            <DivInfo><span>{create_at}</span><span>{author}</span></DivInfo>
            <DivTitle><Link to={`/boards/${name}`}><BoardTitle>{title}</BoardTitle></Link></DivTitle>
            { note !== "" 
            ?
                <DivNote dangerouslySetInnerHTML={getMarkdownText()}></DivNote>
            :
                <DivNote>내용이 없습니다.</DivNote>
            }
        </Item>
    );
}

export default BoardItem