import React, { useEffect, useState } from 'react';
import ReactDOM from 'react-dom';
import {useParams} from 'react-router-dom';
import {BoardWrapper, BoardView} from '../../components/board';

interface boardViewerParamsType {
    paper: string;
}


const BoardViewerLayer:React.FC = ({}) => {
    const {paper} = useParams<boardViewerParamsType>();
    const [paperText, setPaperText] = useState<string>("");

    useEffect(()=>{
        fetch(`/static/papers/${paper}.md`, 
                {
                    method: "GET",
                    headers: {
                        "Content-type": "application/json"
                    },
                }
            )
            .then((value) => value.text())
            .then(text => {
                setPaperText(text);
            });
        return () => {

        }
    }, [paper, paperText]);

    return(
        <BoardWrapper>
            <BoardView text={paperText}></BoardView>
        </BoardWrapper>
    );
}

export default BoardViewerLayer